static int bk7258_wifi_rx_enqueue(struct bk7258_wifi_s *priv,
                                  struct iob_s *iob)
{
  irqstate_t flags;

  flags = enter_critical_section();
  iob->io_flink = NULL;
  if (priv->rx_tail != NULL)
    {
      priv->rx_tail->io_flink = iob;
    }
  else
    {
      priv->rx_head = iob;
    }

  priv->rx_tail = iob;
  leave_critical_section(flags);
  return 0;
}

