	}

	ptr->ref -= 1;

	if (ptr->ref) {
		RWNX_LOGD("release_scan_results later\r\n");
		goto release_exit;
	}

	if (ptr)
		sr_free_all(ptr);
	scan_rst_set_ptr = 0;
	resultful_scan_cfm = 0;

	wpa_clear_scan_results();

release_exit:
	rtos_unlock_mutex(&sr_mutex);
	return;

}

