int wpa_get_scan_rst(struct prism2_hostapd_param *param, int len)
{
	struct wpa_scan_results *results = param->u.scan_rst;
	#if CONFIG_MINIMUM_SCAN_RESULTS
	struct wpa_scan_res *scan_rst_ptr;
	#else
	struct sta_scan_res *scan_rst_ptr;
	struct wpa_scan_res *r;
	#endif
	int i, ret = 0;

	// reduce IEs for scan only
	bool reduce_ie = false;
	bool reduce_scan_result = false;
	u32 ie_len;
	struct wpabuf *ies = 0;
	GLOBAL_INT_DECLARATION();

	GLOBAL_INT_DISABLE();
	wpa_buffer_scan_results();

#ifdef CONFIG_MINIMIZE_SCAN_RESULT_IE
	if (param->sta_addr[0] == 0xFF)
		reduce_ie = true;
#endif
#if CONFIG_MINIMUM_SCAN_RESULTS
	reduce_scan_result = true;
#endif

	if (NULL == s_scan_result_upload_ptr) {
		GLOBAL_INT_RESTORE();
		BK_LOGW(TAG, "get scan result: empty\n");

		if (g_sta_param_ptr->fast_connect_set && g_sta_param_ptr->fast_connect.chann !=0) {
			g_sta_param_ptr->fast_connect_set = 0;
			struct wlan_fast_connect_info fci;
			os_memset(&fci, 0, sizeof(fci));
			wlan_read_fast_connect_info(&fci);

			fci.channel = 0;
			wlan_write_fast_connect_info(&fci);
		}

		/* Don't fail get scan result, but allow empty scan result */
		return 0;
	}

	BK_LOGI(TAG, "get scan result:%d\r\n", s_scan_result_upload_ptr->scanu_num);

	if (reduce_ie && !reduce_scan_result)
		ies = wpabuf_alloc(128);

	for (i = 0; s_scan_result_upload_ptr && i < s_scan_result_upload_ptr->scanu_num; i++) {
		scan_rst_ptr = s_scan_result_upload_ptr->res[i];
		ie_len = 0;
		if (reduce_ie && !reduce_scan_result && ies) {
			wlan_get_bss_beacon_ies(ies, (u8 *)(scan_rst_ptr + 1), scan_rst_ptr->ie_len);
			ie_len = wpabuf_len(ies);
			//BK_LOGD(NULL,"ie_len: %d -> %d\n", scan_rst_ptr->ie_len, ie_len);
		} else {
			ie_len = scan_rst_ptr->ie_len;
		}

#if CONFIG_MINIMUM_SCAN_RESULTS
		scan_rst_ptr->freq = rw_ieee80211_get_centre_frequency(scan_rst_ptr->channel);
		scan_rst_ptr->ie_len = ie_len;
		results->res[results->num++] = scan_rst_ptr;

		if (bk_feature_bssid_connect_enable()) {
			if(os_memcmp(g_sta_param_ptr->fast_connect.bssid, scan_rst_ptr->bssid, ETH_ALEN) == 0) {
				BK_LOGE(TAG, "match specified BSSID " MACSTR  "\r\n", MAC2STR(scan_rst_ptr->bssid));
				os_memset(g_sta_param_ptr->fast_connect.bssid, 0, ETH_ALEN);
			}
		}
#else
		#if CONFIG_PSRAM_AS_SYS_MEMORY
		r = psram_zalloc(sizeof(*r) + ie_len);
		#else
		r = os_zalloc(sizeof(*r) + ie_len);
		#endif
		if (r == NULL) {
			uint32_t total_size,free_size,mini_size;
			#if CONFIG_MEM_DEBUG && CONFIG_FREERTOS
			os_dump_memory_stats(0, 0, NULL);
			#endif
			os_show_memory_config_info();

			total_size = rtos_get_total_heap_size();
			free_size  = rtos_get_free_heap_size();
			mini_size  = rtos_get_minimum_free_heap_size();
			BK_LOGD(TAG, "%-5s   %-5s   %-5s   %-5s   %-5s\r\n","name", "total", "free", "minimum", "peak");
			BK_LOGD(TAG, "heap\t%d\t%d\t%d\t%d\r\n",total_size,free_size,mini_size,total_size-mini_size);

			ret = BK_ERR_NO_MEM;
			BK_LOGE(TAG, "get scan result fail: oom\n");
			break;
		}

		os_memcpy(r->bssid, scan_rst_ptr->bssid, ETH_ALEN);
		r->level = scan_rst_ptr->level;
		r->freq = rw_ieee80211_get_centre_frequency(scan_rst_ptr->channel);
		r->beacon_int = scan_rst_ptr->beacon_int;
		r->caps = scan_rst_ptr->caps;
		r->tsf = WPA_GET_BE64(scan_rst_ptr->tsf);
		r->ie_len = ie_len;
		if (reduce_ie)
			os_memcpy(r + 1, wpabuf_head(ies), wpabuf_len(ies));
		else
		os_memcpy(r + 1, scan_rst_ptr + 1, scan_rst_ptr->ie_len);

		results->res[results->num++] = r;

		if (bk_feature_bssid_connect_enable()) {
			if(os_memcmp(g_sta_param_ptr->fast_connect.bssid, r->bssid, ETH_ALEN) == 0) {
				BK_LOGE(TAG, "match specified BSSID " MACSTR  "\r\n", MAC2STR(r->bssid));
				os_memset(g_sta_param_ptr->fast_connect.bssid, 0, ETH_ALEN);
			}
		}
#endif

		extern uint32_t g_wifi_get_vsie_type;
		const u8 *vendor_ie_elmt = get_vendor_ie((const u8 *)(scan_rst_ptr + 1), scan_rst_ptr->ie_len, g_wifi_get_vsie_type);
		if(vendor_ie_elmt) {
			void * vendor_ie = os_zalloc(scan_rst_ptr->ie_len);
			os_memcpy(vendor_ie, vendor_ie_elmt, vendor_ie_elmt[1]+2);
			bk_wifi_get_vendor_ie_cb_internal(vendor_ie, g_wifi_get_vsie_type, vendor_ie_elmt[1]+2, 1);
		}
	}

	if (reduce_ie && !reduce_scan_result && ies)
		wpabuf_free(ies);

	GLOBAL_INT_RESTORE();

	#if !CONFIG_MINIMUM_SCAN_RESULTS
	/* doesn't need to keep, all info are stored in wpas */
	wpa_hostapd_release_scan_rst();
	#endif
	return ret;
}


