int wpa_driver_scan2(void *priv, struct wpa_driver_scan_params *params)
{
	struct hostap_driver_data *drv = priv;
	struct prism2_hostapd_param *param;
	u8 *buf;
	size_t blen;
	int ret = 0, i;
	int *freqs;

	blen = sizeof(*param) + params->extra_ies_len;
	buf = os_zalloc(blen);
	if (buf == NULL)
		return WPA_ERR_NO_MEM;

	param = (struct prism2_hostapd_param *)buf;
	param->cmd = PRISM2_HOSTAPD_SCAN_REQ;
	param->u.scan_req.ssids_num = MIN(SCAN_SSID_MAX, params->num_ssids);
	if (params->extra_ies != NULL)
		os_memcpy(param->u.scan_req.extra_ies, params->extra_ies, params->extra_ies_len);
	param->u.scan_req.extra_ies_len = params->extra_ies_len;
	param->vif_idx = drv->vif_index;

	os_memcpy(param->u.scan_req.bssid,
		params->bssid ? params->bssid : broadcast_ether_addr, ETH_ALEN);
	for (i = 0; i < param->u.scan_req.ssids_num; i++) {
		param->u.scan_req.ssids[i].ssid_len = params->ssids[i].ssid_len;
		if (params->ssids[i].ssid) {
			os_memcpy(param->u.scan_req.ssids[i].ssid, params->ssids[i].ssid,
						param->u.scan_req.ssids[i].ssid_len);
		}
		if (bk_feature_bssid_connect_enable()) {
			if(params->bssid) {
				os_memcpy(param->u.scan_req.bssid, params->bssid, sizeof(param->u.scan_req.bssid));
			}
		}
		WPA_LOGV("%s: Scan specified BSSID " MACSTR  "\n", __func__, MAC2STR(param->u.scan_req.bssid));
	}

	freqs = params->freqs;
	if (freqs) {
		for (i = 0; i < ARRAY_SIZE(param->u.scan_req.freqs); i++, freqs++) {
			if (!*freqs)
				break;
			param->u.scan_req.freqs[i] = *freqs;
		}
	}

	if (hostapd_ioctl(drv, param, blen))
		ret = WPA_ERR_SCAN_REQ;

	os_free(buf);

	if (!ret && drv->wpa_s) {
		eloop_cancel_timeout(wpa_driver_scan_timeout, drv->wpa_s, NULL);
		eloop_register_timeout(10, 0, wpa_driver_scan_timeout,
				       drv->wpa_s, NULL);
	}

	return ret;
}


struct wpa_scan_results *wpa_driver_get_scan_results2(void *priv)
{
	struct hostap_driver_data *drv = priv;
	struct prism2_hostapd_param *param;
	struct wpa_scan_results *results = NULL;
	u8 *buf;
	size_t blen;
	int ret = 0;
	struct wpa_supplicant *wpa_s = drv->wpa_s;

	blen = sizeof(*param);
	buf = os_zalloc(blen);
	if(buf == NULL) {
		goto fail_result;
	}

	param = (struct prism2_hostapd_param *)buf;
	param->cmd = PRISM2_HOSTAPD_GET_SCAN_RESULT;
	param->vif_idx = drv->vif_index;
	if (wpa_s) {
		if (wpa_s->scan_res_handler == scan_only_handler)
			param->sta_addr[0] = 0xFF;
	}

	results = os_zalloc(sizeof(*results));
	if(results == NULL) {
		goto fail_result;
	}
	results->res = os_calloc(MAX_BSS_LIST, sizeof(struct wpa_scan_res *));
	if (results->res == NULL) {
		goto fail_result;
	}

	param->u.scan_rst = results;

	if (hostapd_ioctl(drv, param, blen)) {
		ret = -1;
	}

	if(!ret) {
		os_free(buf);
		return results;
	}

fail_result:
	os_free(buf);
	#if CONFIG_MINIMUM_SCAN_RESULTS
	wpa_hostapd_release_scan_rst();
	#endif
	wpa_scan_results_free(results);
	return NULL;
}

int wpa_driver_associate(void *priv, struct wpa_driver_associate_params *params)
{
	struct hostap_driver_data *drv = priv;

  if (required > UINT16_MAX || iwr->u.data.pointer == NULL ||
      required > iwr->u.data.length)
    {
      iwr->u.data.length = required > UINT16_MAX ? UINT16_MAX : required;
      nxmutex_unlock(&priv->scan_lock);
      return -E2BIG;
    }

  {
    FAR uint8_t *cursor = iwr->u.data.pointer;

    for (index = 0; index < priv->scan_count; index++)
      {
        FAR struct iw_event *iwe = (FAR struct iw_event *)cursor;
        FAR struct bk7258_wifi_scan_ap_s *ap = &priv->scan_aps[index];
        iwe->cmd = SIOCGIWAP;
        iwe->u.ap_addr.sa_family = ARPHRD_ETHER;
        memcpy(iwe->u.ap_addr.sa_data, ap->bssid, sizeof(ap->bssid));
        iwe->len = IW_EV_LEN(ap_addr);
        cursor += iwe->len;

        ssid_len = strnlen(ap->ssid, BK7258_WIFI_SCAN_SSID_LEN);
        iwe = (FAR struct iw_event *)cursor;
        iwe->cmd = SIOCGIWESSID;
        iwe->u.essid.flags = 0;
        iwe->u.essid.length = ssid_len;
        iwe->u.essid.pointer = (FAR void *)sizeof(iwe->u.essid);
        memcpy(&iwe->u.essid + 1, ap->ssid, ssid_len);
        iwe->len = IW_EV_LEN(essid) + ((ssid_len + 3u) & ~3u);
        cursor += iwe->len;

        iwe = (FAR struct iw_event *)cursor;
        iwe->cmd = IWEVQUAL;
        iwe->u.qual.qual = 0;
        iwe->u.qual.level = (uint8_t)ap->rssi;
        iwe->u.qual.noise = 0;
        iwe->u.qual.updated = IW_QUAL_LEVEL_UPDATED | IW_QUAL_DBM |
                              IW_QUAL_QUAL_INVALID | IW_QUAL_NOISE_INVALID;
        iwe->len = IW_EV_LEN(qual);
        cursor += iwe->len;

        iwe = (FAR struct iw_event *)cursor;
        iwe->cmd = SIOCGIWFREQ;
        /* WEXT represents values 0..1000 as a channel number. This avoids
         * inventing a frequency conversion for a future/non-2.4GHz result. */
        iwe->u.freq.e = 0;
        iwe->u.freq.m = ap->channel;
        iwe->len = IW_EV_LEN(freq);
        cursor += iwe->len;

        iwe = (FAR struct iw_event *)cursor;
        iwe->cmd = SIOCGIWENCODE;
        iwe->u.data.flags = ap->security == WIFI_SECURITY_NONE ?
                            IW_ENCODE_DISABLED :
                            IW_ENCODE_ENABLED | IW_ENCODE_NOKEY;
        iwe->u.data.length = 0;
        iwe->u.data.pointer = NULL;
        iwe->len = IW_EV_LEN(data);
        cursor += iwe->len;
      }

    iwr->u.data.length = cursor - (FAR uint8_t *)iwr->u.data.pointer;
  }

  nxmutex_unlock(&priv->scan_lock);
  return OK;
#else
  (void)lower;
  (void)iwr;
  (void)set;
  return -ENOSYS;
#endif
}

