int bk7258_wifi_lower_init(struct bk7258_wifi_s *priv)
{
  memset(priv, 0, sizeof(*priv));

  priv->sta_mode = IW_MODE_INFRA;

  if (nxmutex_init(&priv->scan_lock) < 0)
    {
